000021 | /** Local JNDI compatibility database for the bundled N2 runtime. */
000022 | public final class H2JndiSetupListener implements ServletContextListener {
000023 | 	private static final String LOCAL_DATABASE_PROPERTY = "n2nenkin.localDb";
000024 | 
000025 | 	private static final String[] JNDI_NAMES = {
000026 | 		"jdbc/Oracle_SP2NM", "jdbc/Oracle_DWH", "jdbc/RAROA_DB", "jdbc/RAROA_SHARE"
000027 | 	};
000028 | 
000029 | 	private JdbcDataSource dataSource;
000030 | 
000031 | 	public void contextInitialized(ServletContextEvent event) {
000032 | 		ServletContext context = event.getServletContext();
000033 | 		if (!Boolean.parseBoolean(System.getProperty(LOCAL_DATABASE_PROPERTY, "false"))) {
000034 | 			context.log("Local H2 compatibility database is disabled; using the N2 container JNDI database.");
000035 | 			return;
000036 | 		}
000037 | 		try {
000038 | 			File databaseFile = resolveDatabaseFile(context);
000039 | 			File directory = databaseFile.getParentFile();
000040 | 			if (!directory.exists() && !directory.mkdirs()) {
000041 | 				throw new IllegalStateException("Cannot create database directory: " + directory);
000042 | 			}
000043 | 
000044 | 			dataSource = new JdbcDataSource();
000045 | 			dataSource.setURL(createJdbcUrl(databaseFile));
000048 | 			initializeDatabase(context);
000049 | 			bindDataSource();
000050 | 			context.log("N2 pension compatibility database initialized: " + databaseFile.getAbsolutePath());
000051 | 		} catch (Exception e) {
000052 | 			context.log("N2 pension compatibility database initialization failed.", e);
000053 | 			throw new IllegalStateException("Database initialization failed.", e);
000054 | 		}
000055 | 	}
000056 | 
000057 | 	public void contextDestroyed(ServletContextEvent event) {
000058 | 		if (dataSource == null) return;
000059 | 		unbindDataSource();
000060 | 		shutdownDatabase(event.getServletContext());
000061 | 	}
000062 | 
000063 | 	private File resolveDatabaseFile(ServletContext context) {
000064 | 		String overridePath = System.getProperty("n2nenkin.db.path");
000065 | 		if (overridePath != null && overridePath.trim().length() > 0) {
000066 | 			return new File(overridePath.trim()).getAbsoluteFile();
000067 | 		}
000068 | 		String directory = context.getRealPath("/WEB-INF/local-db");
000069 | 		if (directory == null) throw new IllegalStateException("Expanded deployment is required for local H2.");
000070 | 		return new File(directory, "nenkin").getAbsoluteFile();
000071 | 	}
000072 | 
000073 | 	private String createJdbcUrl(File databaseFile) {
000074 | 		return "jdbc:h2:file:" + databaseFile.getAbsolutePath().replace('\\', '/')
000075 | 			+ ";MODE=Oracle;DATABASE_TO_UPPER=TRUE;CASE_INSENSITIVE_IDENTIFIERS=FALSE";
000076 | 	}
000077 | 
000078 | 	private void initializeDatabase(ServletContext context) throws Exception {
000079 | 		Connection connection = null;
000080 | 		try {
000081 | 			connection = dataSource.getConnection();
000082 | 			runScript(context, connection, "/WEB-INF/resources/db/schema.sql");
000083 | 			runScript(context, connection, "/WEB-INF/resources/db/data.sql");
000084 | 		} finally {
000085 | 			if (connection != null) connection.close();
000086 | 		}
000087 | 	}
000088 | 
000089 | 	private void runScript(ServletContext context, Connection connection, String path) throws Exception {
000090 | 		InputStream stream = context.getResourceAsStream(path);
000091 | 		if (stream == null) throw new IllegalStateException("Database resource not found: " + path);
000092 | 		Reader reader = null;
000093 | 		try {
000094 | 			reader = new InputStreamReader(stream, "UTF-8");
000095 | 			RunScript.execute(connection, reader);
000096 | 		} finally {
000097 | 			if (reader != null) reader.close(); else stream.close();
000098 | 		}
000099 | 	}
000100 | 
000101 | 	private void bindDataSource() throws NamingException {
000102 | 		InitialContext context = new InitialContext();
000103 | 		try { context.createSubcontext("jdbc"); } catch (NameAlreadyBoundException e) { }
000104 | 		for (int i = 0; i < JNDI_NAMES.length; i++) context.rebind(JNDI_NAMES[i], dataSource);
000105 | 	}
000106 | 
000107 | 	private void unbindDataSource() {
000108 | 		try {
000109 | 			Context context = new InitialContext();
000110 | 			for (int i = 0; i < JNDI_NAMES.length; i++) {
000111 | 				try { context.unbind(JNDI_NAMES[i]); } catch (NamingException e) { }
000112 | 			}
000113 | 		} catch (NamingException e) { }
000114 | 	}
000115 | 
000116 | 	private void shutdownDatabase(ServletContext context) {
000117 | 		if (dataSource == null) return;
000118 | 		Connection connection = null;
000119 | 		Statement statement = null;
000120 | 		try {
000121 | 			connection = dataSource.getConnection();
000122 | 			statement = connection.createStatement();
000123 | 			statement.execute("SHUTDOWN");
000124 | 		} catch (Exception e) {
000125 | 			context.log("H2 shutdown failed.", e);
000126 | 		} finally {
000127 | 			try { if (statement != null) statement.close(); } catch (Exception e) { }
000128 | 			try { if (connection != null) connection.close(); } catch (Exception e) { }
000129 | 		}
000130 | 	}
000131 | }
